import java.io.*;
import java.nio.*;
import java.nio.channels.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

/**
 * Fast, bounded HPROF 1.0.2 primitive-array owner census.  It reports incoming
 * references, not retained size.  Compile with JDK 21:
 * javac HprofOwnersFast.java; java HprofOwnersFast dump.hprof out-prefix
 */
public final class HprofOwnersFast {
  static final int STRING=1, LOAD=2, HEAP=0x0c, SEG=0x1c, CLASS=0x20, INST=0x21, OBJARR=0x22, PRIM=0x23;
  static final long MAP=1L<<30, SPLIT=32L<<20; static int ids; static Bytes data;
  static final Map<Long,String> strings=new HashMap<>(); static final Map<Long,Long> loads=new HashMap<>(); static final Map<Long,Cls> classes=new HashMap<>();
  static final Map<Long,Arr> arrays=new HashMap<>(); static final List<Range> work=new ArrayList<>(); static final List<String> warnings=Collections.synchronizedList(new ArrayList<>());
  record Field(long name,int type,long owner){} record Cls(long id,long sup,int shallow,List<Field> fields,List<Static> statics){} record Static(long name,int type,long value){}
  record Arr(long id,int type,long len,long bytes,long offset){} record Range(long a,long b){}
  static final class Bytes implements Closeable { final FileChannel ch; final MappedByteBuffer[] maps; final long size;
    Bytes(Path p)throws IOException{ch=FileChannel.open(p);size=ch.size(); int n=(int)((size+MAP-1)/MAP);maps=new MappedByteBuffer[n];for(int i=0;i<n;i++){long o=(long)i*MAP;maps[i]=ch.map(FileChannel.MapMode.READ_ONLY,o,Math.min(MAP,size-o));}}
    byte b(long p){return maps[(int)(p/MAP)].get((int)(p%MAP));} int u1(long p){return b(p)&255;} int u2(long p){return(u1(p)<<8)|u1(p+1);} long u4(long p){return ((long)u1(p)<<24)|((long)u1(p+1)<<16)|((long)u1(p+2)<<8)|u1(p+3);} long id(long p){long v=0;for(int i=0;i<ids;i++)v=(v<<8)|u1(p+i);return v;} String text(long a,long z){byte[] x=new byte[(int)Math.min(z-a,4096)];for(int i=0;i<x.length;i++)x[i]=b(a+i);return new String(x,StandardCharsets.UTF_8);} public void close()throws IOException{ch.close();}}
  static int sz(int t){return switch(t){case 2->ids;case 4,8->1;case 5,9->2;case 6,10->4;case 7,11->8;default->throw new IllegalArgumentException("type "+t);};}
  static long primEnd(long p){long n=data.u4(p+ids+4), q=p+ids+9; return q+n*sz(data.u1(p+ids+8));}
  static long classEnd(long p){long q=p+ids+4+ids*6+4;int n=data.u2(q);q+=2;for(int i=0;i<n;i++){int t=data.u1(q+2);q+=3+sz(t);}n=data.u2(q);q+=2;for(int i=0;i<n;i++){int t=data.u1(q+ids);q+=ids+1+sz(t);}return q+2+(long)data.u2(q)*(ids+1);}
  static long end(int tag,long p){return switch(tag){case 1,2,3,4,5,6,7,8,0xff->p+ids+switch(tag){case 1->ids;case 2,3,8->8;case 4,6->4;default->0;};case 0xfe->p+4+ids;case CLASS->classEnd(p);case INST->p+ids+4+ids+4+data.u4(p+ids+4+ids);case OBJARR->{long n=data.u4(p+ids+4);yield p+ids+4+4+ids+n*ids;}case PRIM->primEnd(p);default->throw new IllegalArgumentException("unknown heap tag "+tag+" @"+p);};}
  static void classMeta(long p){long id=data.id(p), sup=data.id(p+ids+4),q=p+ids+4+ids*6,shallow=data.u4(q);q+=4;int n=data.u2(q);q+=2;for(int i=0;i<n;i++){int t=data.u1(q+2);q+=3+sz(t);}n=data.u2(q);q+=2;ArrayList<Static>s=new ArrayList<>();for(int i=0;i<n;i++){long name=data.id(q);int t=data.u1(q+ids);q+=ids+1;long v=t==2?data.id(q):0;q+=sz(t);s.add(new Static(name,t,v));}n=data.u2(q);q+=2;ArrayList<Field>f=new ArrayList<>();for(int i=0;i<n;i++){f.add(new Field(data.id(q),data.u1(q+ids),id));q+=ids+1;}classes.put(id,new Cls(id,sup,(int)shallow,f,s));}
  static void firstHeap(long a,long z){long p=a,last=a;while(p<z){int t=data.u1(p++);long e=end(t,p);if(t==CLASS)classMeta(p);if(t==PRIM){long id=data.id(p),n=data.u4(p+ids+4),bytes=n*sz(data.u1(p+ids+8));if(bytes>=4096&&arrays.size()<1_000_000)arrays.put(id,new Arr(id,data.u1(p+ids+8),n,bytes,p+ids+9));}if(e-last>=SPLIT){work.add(new Range(last,e));last=e;}p=e;}if(last<z)work.add(new Range(last,z));}
  static String name(long c){Long s=loads.get(c);return s==null?"<class#"+Long.toHexString(c)+">":strings.getOrDefault(s,"<string#"+Long.toHexString(s)+">");}
  static List<Field> layout(long c){ArrayList<Field>r=new ArrayList<>();for(int k=0;k<64&&c!=0;k++){Cls x=classes.get(c);if(x==null)return List.of();r.addAll(x.fields);c=x.sup;}return r;}
  static final Map<Long,List<Field>> layouts=new HashMap<>();
  static long processCpu(){return ((com.sun.management.OperatingSystemMXBean)java.lang.management.ManagementFactory.getOperatingSystemMXBean()).getProcessCpuTime();}
  static final ConcurrentHashMap<String,Group> groups=new ConcurrentHashMap<>(); static final ConcurrentHashMap<Long,ConcurrentHashMap.KeySetView<String,Boolean>> shared=new ConcurrentHashMap<>();
  static final ConcurrentHashMap<String,LongAdder> censusBytes=new ConcurrentHashMap<>(), censusCount=new ConcurrentHashMap<>();
  static final ConcurrentHashMap<Long,Arr> bitsetArray=new ConcurrentHashMap<>(); static final Set<Long> yungArrays=ConcurrentHashMap.newKeySet();
  static final Set<Long> bitsets=ConcurrentHashMap.newKeySet(); static final ConcurrentHashMap<Long,Long> bitsetWords=new ConcurrentHashMap<>(); static final ConcurrentHashMap<String,LongAdder> bitsetParents=new ConcurrentHashMap<>(),bitsetParentBytes=new ConcurrentHashMap<>(); static final LongAdder bitsetWordsUntracked=new LongAdder(),objectArrayElements=new LongAdder();
  static final Set<Long> top=ConcurrentHashMap.newKeySet(); static final ConcurrentHashMap<Long,ConcurrentLinkedQueue<String>> incoming=new ConcurrentHashMap<>();
  static final class Group{final LongAdder refs=new LongAdder(),bytes=new LongAdder();final ConcurrentHashMap.KeySetView<Long,Boolean> seen=ConcurrentHashMap.newKeySet();void add(Arr a){refs.increment();if(seen.add(a.id))bytes.add(a.bytes);}}
  static void census(String key,long bytes){censusBytes.computeIfAbsent(key,k->new LongAdder()).add(bytes);censusCount.computeIfAbsent(key,k->new LongAdder()).increment();}
  static void hit(String g,long target,long owner,long index){Arr a=arrays.get(target);if(a==null)return;groups.computeIfAbsent(g,k->new Group()).add(a);shared.computeIfAbsent(target,k->ConcurrentHashMap.newKeySet()).add(g);if(top.contains(target))incoming.computeIfAbsent(target,k->new ConcurrentLinkedQueue<>()).add(g+" owner=0x"+Long.toHexString(owner)+(index>=0?" index="+index:""));}
  static void scan(Range r){long p=r.a;while(p<r.b){int t=data.u1(p++);long e=end(t,p);if(t==INST){long owner=data.id(p),c=data.id(p+ids+4),q=p+ids+4+ids+4;Cls ci=classes.get(c);boolean bs=ci!=null&&name(c).equals("java/util/BitSet");if(ci!=null)census("instance\t"+name(c),ci.shallow);if(bs)bitsets.add(owner);for(Field f:layouts.getOrDefault(c,List.of())){int n=sz(f.type);if(f.type==2){long target=data.id(q);if(bs&&strings.getOrDefault(f.name,"").equals("words")){Arr a=arrays.get(target);if(a==null)bitsetWordsUntracked.increment();else {bitsetWords.put(owner,a.bytes);bitsetArray.put(owner,a);}}if(arrays.containsKey(target))hit("field\t"+name(f.owner)+"\t"+strings.getOrDefault(f.name,"<field>"),target,owner,-1);}q+=n;}}else if(t==OBJARR){long owner=data.id(p),n=data.u4(p+ids+4),c=data.id(p+ids+8),q=p+ids+8+ids;objectArrayElements.add(n);String g="array\t"+name(c)+"\t[]";census(g,n*ids);for(long i=0;i<n;i++,q+=ids)hit(g,data.id(q),owner,i);}else if(t==PRIM){long n=data.u4(p+ids+4);int typ=data.u1(p+ids+8);census("primitive\ttype"+typ+"[]",n*sz(typ));}else if(t==CLASS){Cls c=classes.get(data.id(p));if(c!=null)for(Static s:c.statics)if(s.type==2)hit("static\t"+name(c.id)+"\t"+strings.getOrDefault(s.name,"<field>"),s.value,c.id,-1);}p=e;}}
  static void bitsetParents(Range r){long p=r.a;while(p<r.b){int t=data.u1(p++);long e=end(t,p);if(t==INST){long c=data.id(p+ids+4),q=p+ids+4+ids+4;for(Field f:layouts.getOrDefault(c,List.of())){int n=sz(f.type);if(f.type==2&&bitsets.contains(data.id(q)))bitsetParents.computeIfAbsent(name(f.owner)+"."+strings.getOrDefault(f.name,"<field>"),k->new LongAdder()).increment();q+=n;}}p=e;}}
  static void traceBitsetParents(Range r){long p=r.a;while(p<r.b){int t=data.u1(p++);long e=end(t,p);if(t==INST){long c=data.id(p+ids+4),q=p+ids+4+ids+4;for(Field f:layouts.getOrDefault(c,List.of())){int n=sz(f.type);if(f.type==2){Long bytes=bitsetWords.get(data.id(q));if(bytes!=null){String k=name(f.owner)+"."+strings.getOrDefault(f.name,"<field>");if(k.endsWith("AquiferOverrideMask.mask"))yungArrays.add(bitsetArray.get(data.id(q)).id);bitsetParents.computeIfAbsent(k,z->new LongAdder()).increment();bitsetParentBytes.computeIfAbsent(k,z->new LongAdder()).add(bytes);}}q+=n;}}p=e;}}

  static void auditYung(String prefix)throws IOException {
    long all=0,zeroBytes=0,zeros=0,nonzeroWords=0,trimmedBytes=0;
    for(long id:yungArrays){Arr a=arrays.get(id);long last=-1;all+=a.bytes;
      for(long i=0;i<a.len;i++){long pos=a.offset+i*8;if(data.u4(pos)!=0||data.u4(pos+4)!=0){last=i;nonzeroWords++;}}
      if(last<0){zeros++;zeroBytes+=a.bytes;}trimmedBytes+=(last+1)*8;
    }
    try(PrintWriter w=new PrintWriter(prefix+"-extra-summary.tsv")){
      w.println("metric\tvalue");w.println("yungArrays\t"+yungArrays.size());w.println("yungPayloadBytes\t"+all);
      w.println("yungAllZeroArrays\t"+zeros);w.println("yungAllZeroPayloadBytes\t"+zeroBytes);
      w.println("yungNonzeroWords\t"+nonzeroWords);w.println("yungExactTrimmedPayloadBytes\t"+trimmedBytes);
      w.println("allCensusPayloadAndDeclaredFieldBytes\t"+censusBytes.values().stream().mapToLong(LongAdder::sum).sum());
      w.println("objectArrayElementPayloadDeltaOnly\t"+(objectArrayElements.sum()*4));
    }
  }
  static void progress(String phase,long wall,long cpu){System.out.printf("%s wallMs=%d cpuMs=%d arrays=%d ranges=%d%n",phase,wall,cpu,arrays.size(),work.size());}
  public static void main(String[]x)throws Exception{if(x.length<2){System.err.println("usage: HprofOwnersFast dump.hprof out-prefix [threads]");return;}long wall=System.nanoTime(),cpu=processCpu();data=new Bytes(Path.of(x[0]));long nul=0;while(data.u1(nul)!=0)nul++;ids=(int)data.u4(nul+1);long p=nul+13;while(p<data.size){int t=data.u1(p);long z=p+9+data.u4(p+5),b=p+9;if(t==STRING)strings.put(data.id(b),data.text(b+ids,z));else if(t==LOAD)loads.put(data.id(b+4),data.id(b+4+ids+4));else if(t==HEAP||t==SEG)firstHeap(b,z);p=z;}arrays.values().stream().sorted((a,b)->Long.compare(b.bytes,a.bytes)).limit(1000).forEach(a->top.add(a.id));progress("metadata",(System.nanoTime()-wall)/1_000_000,(processCpu()-cpu)/1_000_000);for(long c:classes.keySet())layouts.put(c,layout(c));ExecutorService ex=Executors.newFixedThreadPool(x.length>2?Integer.parseInt(x[2]):Math.min(12,Runtime.getRuntime().availableProcessors()));List<Future<?>> tasks=new ArrayList<>();for(Range r:work)tasks.add(ex.submit(()->scan(r)));ex.shutdown();for(Future<?> task:tasks)task.get();ex.awaitTermination(7,TimeUnit.DAYS);progress("owners",(System.nanoTime()-wall)/1_000_000,(processCpu()-cpu)/1_000_000);ExecutorService parentPool=Executors.newFixedThreadPool(x.length>2?Integer.parseInt(x[2]):12);List<Future<?>> parentTasks=new ArrayList<>();for(Range r:work)parentTasks.add(parentPool.submit(()->traceBitsetParents(r)));parentPool.shutdown();for(Future<?> task:parentTasks)task.get();auditYung(x[1]);progress("parentTraceAndContent",(System.nanoTime()-wall)/1_000_000,(processCpu()-cpu)/1_000_000);try(PrintWriter b=new PrintWriter(x[1]+"-bitset-parents.tsv")){b.println("ownerField\tbitSetsWithTrackedWords\twordsPayloadBytesPerIncomingReference");bitsetParents.entrySet().stream().sorted((a,c)->Long.compare(bitsetParentBytes.get(c.getKey()).sum(),bitsetParentBytes.get(a.getKey()).sum())).forEach(e->b.printf("%s\t%d\t%d%n",e.getKey(),e.getValue().sum(),bitsetParentBytes.get(e.getKey()).sum()));b.println("#untrackedWordsArrays\t"+bitsetWordsUntracked.sum());}System.out.println("objectArrayElements="+objectArrayElements.sum()+" hypotheticalCompressedOopsArrayPayloadDelta="+(objectArrayElements.sum()*4));try(PrintWriter o=new PrintWriter(x[1]+"-owners.tsv")){o.println("kind\townerClass\tfield\treferences\tuniqueArrays\tuniquePayloadBytes");groups.entrySet().stream().sorted((a,b)->Long.compare(b.getValue().bytes.sum(),a.getValue().bytes.sum())).forEach(e->{String[]q=e.getKey().split("\\t",3);Group g=e.getValue();o.printf("%s\t%s\t%s\t%d\t%d\t%d%n",q[0],q[1],q[2],g.refs.sum(),g.seen.size(),g.bytes.sum());});}try(PrintWriter o=new PrintWriter(x[1]+"-arrays.tsv")){o.println("id\ttype\tlength\tpayloadBytes\tpayloadOffset\tgroups\tincoming");arrays.values().stream().sorted((a,b)->Long.compare(b.bytes,a.bytes)).limit(1000).forEach(a->o.printf("0x%x\t%d\t%d\t%d\t%d\t%d\t%s%n",a.id,a.type,a.len,a.bytes,a.offset,shared.getOrDefault(a.id,ConcurrentHashMap.newKeySet()).size(),String.join(" | ",incoming.getOrDefault(a.id,new ConcurrentLinkedQueue<>())).replace("\t"," ")));}try(PrintWriter o=new PrintWriter(x[1]+"-array-groups.tsv")){o.println("id\ttype\tlength\tpayloadBytes\tpayloadOffset\townerGroups");for(Arr a:arrays.values())o.printf("0x%x\t%d\t%d\t%d\t%d\t%s%n",a.id,a.type,a.len,a.bytes,a.offset,String.join(" | ",shared.getOrDefault(a.id,ConcurrentHashMap.newKeySet())).replace("\t"," "));}try(PrintWriter o=new PrintWriter(x[1]+"-census.tsv")){o.println("kind\tclassOrArray\tcount\tshallowOrPayloadBytes");censusBytes.entrySet().stream().filter(e->e.getValue().sum()>=32L*1024*1024).sorted((a,b)->Long.compare(b.getValue().sum(),a.getValue().sum())).forEach(e->o.printf("%s\t%d\t%d%n",e.getKey(),censusCount.get(e.getKey()).sum(),e.getValue().sum()));}data.close();}
  }
